def center(size, l, x, y):
    for i in range(size):
        for j in range(size):
            l[i + x][j + y] = '.'

def generate_carpet(n):
    size = 3 ** n
    lk = [['#' for _ in range(size)] for _ in range(size)]

    if n == 0:
        print('#')
    elif n == 1:
        l0 = [
            ['#', '#', '#'],
            ['#', '.', '#'],
            ['#', '#', '#']
        ]
        for i in l0:
            print(*i, sep='')
    else:
        def fill_carpet(level, x, y):
            if level == 0:
                return
            size = 3 ** level
            size_low = 3 ** (level - 1)
            center(size_low, lk, x + size_low, y + size_low)
            for i in range(3):
                for j in range(3):
                    if i == 1 and j == 1:
                        continue
                    fill_carpet(level - 1, x + i * size_low, y + j * size_low)

        fill_carpet(n, 0, 0)

        for i in lk:
            print(*i, sep='')

n = int(input())
generate_carpet(n)
